How can I write a function in Go that accepts a string and returns a new string where every even-indexed character is converted to uppercase and every odd-indexed character is converted to lowercase?
[Go code]
func convertString(str string) string {
    var result string
    for i := 0; i < len(str); i++ {
        if i%2 == 0 {
            result += strings.ToUpper(string(str[i]))
        } else {
            result += strings.ToLower(string(str[i]))
        }
    }
    return result
}

