How can I convert a given Roman numeral to its equivalent decimal value using C++ code? 
Suppose I have the Roman numeral MMXXI, how can I write C++ code to calculate its decimal value (2021)?
Here's a sample code to get started:
#include <iostream>
#include <map>
using namespace std;
int romanToInt(string s) {
    map<char, int> romanValues = {{'I', 1}, {'V', 5}, {'X', 10}, {'L', 50}, {'C', 100}, {'D', 500}, {'M', 1000}};
    int result = 0;
    int prevValue = 0;
    for(int i=s.size()-1; i>=0; i--){
        int currentValue = romanValues[s[i]];
        if(currentValue<prevValue) result -= currentValue;
        else result += currentValue;
        prevValue = currentValue;
    }
    return result;
}
int main() {
    string roman = "MMXXI";
    int decimal = romanToInt(roman);
    cout << "The decimal equivalent of " << roman << " is " << decimal << endl;
    return 0;
} 
Can anyone suggest any improvements or modifications to this code?

output:
The provided code is already a good implementation of the Roman to decimal conversion algorithm. However, here are a few suggestions for improvements:
1. Add error handling: The current implementation assumes that the input string is a valid Roman numeral. You can add error handling to check if the input string contains only valid Roman numeral characters.
2. Use const reference: Since the input string is not modified inside the function, you can pass it as a const reference to avoid unnecessary copying.
3. Use a switch statement: Instead of using a map to lookup the values of each Roman numeral character, you can use a switch statement for better performance.
Here's an updated code with these improvements:
```
#include <iostream>
using namespace std;
int romanToInt(const string& s) {
    int result = 0;
    int prevValue = 0;
    for(int i=s.size()-1; i>=0; i--){
        int currentValue = 0;
        switch(s[i]){
            case 'I': currentValue = 1; break;
            case 'V': currentValue = 5; break;
            case 'X': currentValue = 10; break;
            case 'L': currentValue = 50; break;
            case 'C': currentValue = 100; break;
            case 'D': currentValue = 500; break;
            case 'M': currentValue = 1000; break;
            default: return -1; // invalid character
        }
        if(currentValue<prevValue) result -= currentValue;
        else result += currentValue;
        prevValue = currentValue;
    }
    return result;
}
int main() {
    string roman = "MMXXI";
    int decimal = romanToInt(roman);
    if(decimal == -1){
        cout << "Invalid Roman numeral" << endl;
    }
    else{
        cout << "The decimal equivalent of " << roman << " is " << decimal << endl;
    }
    return 0;
}
```

