Here's an example Go code that can generate these descriptions:
```
package main
import (
    "fmt"
)
type Person struct {
    Name       string
    Work       string
    Education  string
    Achieve    string
    Interest   string
    Contribution string
}
func main() {
    people := []Person{
        {"Olivia", "successful lawyer", "Harvard Law School graduate", "advocate for women's rights", "speeches about gender equality in the legal system", ""},
        {"Robert", "renowned architect", "", "iconic building designs", "", "mentoring of young architects, volunteer work in building sustainable homes for underprivileged communities"},
    }
    for _, person := range people {
        fmt.Printf("\\textbf{%s} - %s\n", person.Name, person.Work)
        fmt.Printf("\\textit{%s}\n", person.Education)
        fmt.Printf("\\begin{itemize}\n")
        if person.Achieve != "" {
            fmt.Printf("\\item %s\n", person.Achieve)
        }
        if person.Interest != "" {
            fmt.Printf("\\item %s\n", person.Interest)
        }
        if person.Contribution != "" {
            fmt.Printf("\\item %s\n", person.Contribution)
        }
        fmt.Printf("\\end{itemize}\n\n")
    }
}
