        return false;
    }
    unordered_map<char, int> charMap;
    int countA = 0;
    int posA1 = -1;
    int posA2 = -1;
    for (int i = 0; i < str.length(); i++) {
        char c = str[i];
        if (charMap.find(c) != charMap.end()) {
            return false;
        } else {
            charMap[c] = 1;
        }
