Here's a PHP script that extracts information from a FIFA website XML data source for the five host cities of the 2010 World Cup, arranges the city-country information and population data in descending order based on their population density per square kilometer, and includes the latitude and longitude coordinates of each city in the output:
```
<?php
// Define the XML data source
$xml = simplexml_load_file('http://www.fifa.com/worldcup/archive/southafrica2010/statistics/cities.xml');
// Define an array to store the city data
$cities = array();
// Loop through the XML data and extract the city data
foreach ($xml->city as $city) {
    $city_name = (string) $city->name;
    $country_name = (string) $city->country;
    $population = (int) $city->population;
    $area = (float) $city->area;
    $latitude = (float) $city->latitude;
    $longitude = (float) $city->longitude;
    // Calculate the population density per square kilometer
    $density = $population / $area;
    // Add the city data to the array
    $cities[] = array(
        'city_name' => $city_name,
        'country_name' => $country_name,
        'population' => $population,
        'area' => $area,
        'density' => $density,
        'latitude' => $latitude,
        'longitude' => $longitude
    );
}
// Sort the city data in descending order based on population density
usort($cities, function($a, $b) {
    return $b['density'] - $a['density'];
});
// Output the city data
foreach ($cities as $city) {
    echo $city['city_name'] . ', ' . $city['country_name'] . ' - Population Density: ' . number_format($city['density'], 2) . ' people per square kilometer (Population: ' . number_format($city['population']) . ', Area: ' . number_format($city['area'], 2) . ' square kilometers, Latitude: ' . $city['latitude'] . ', Longitude: ' . $city['longitude'] . ')' . "\n";
}
