```java
import java.util.ArrayList;
import java.util.Collections;
public class GeometricMean {
    public static void main(String[] args) {
        ArrayList<Double> sides = new ArrayList<Double>();
        double longest = 0.0;
        double shortest = Double.MAX_VALUE;
        // Generate random number of sides between 5 and 15 (inclusive)
        int numSides = (int) (Math.random() * 11) + 5;
        // Generate random side lengths between 1 and 10 (inclusive)
        for (int i = 0; i < numSides; i++) {
            double side = Math.random() * 10 + 1;
            sides.add(side);
            if (side > longest) {
                longest = side;
            }
            if (side < shortest) {
                shortest = side;
            }
        }
        // Ensure that the polygon has an odd number of sides
        if (numSides % 2 == 0) {
            sides.remove(Collections.max(sides));
            numSides--;
        }
        // Ensure that the ratio of the longest side to the shortest side does not exceed 3
        while (longest / shortest > 3) {
            sides.remove(Collections.max(sides));
            numSides--;
            longest = Collections.max(sides);
            shortest = Collections.min(sides);
        }
        // Calculate the geometric mean of the side lengths
        double product = 1.0;
        for (double side : sides) {
            product *= side;
        }
        double geometricMean = Math.pow(product, 1.0 / numSides);
        System.out.println("Number of sides: " + numSides);
        System.out.println("Longest side: " + longest);
        System.out.println("Shortest side: " + shortest);
        System.out.println("Geometric mean of side lengths: " + geometricMean);
    }
}
```
This code generates a random number of sides and side lengths for an irregular polygon, then removes sides until the polygon has an odd number of sides and the ratio of the longest side to the shortest side does not exceed 3. Finally, it calculates the geometric mean of the remaining side lengths and prints the results.

